SELECT *
FROM app_role_permission
WHERE role_id = #{roleId}
  AND status = #{status}
ORDER BY id ASC

SELECT *
FROM app_role_permission
WHERE role_id IN

  #{roleId}

  AND status = #{status}
ORDER BY role_id ASC, id ASC

SELECT *
FROM app_role_permission
WHERE role_id = #{roleId}
  AND permission_id = #{permissionId}

  AND effect = #{effect}

  AND status = #{status}
ORDER BY id ASC
LIMIT 1
